import{_ as a,o,c as e,a2 as r}from"./chunks/framework.RQXGjTIX.js";const i="/appliedcraftedenergistics/gas-p2p.png",q=JSON.parse('{"title":"气体 P2P 隧道","description":"","frontmatter":{},"headers":[],"relativePath":"guide/p2p.md","filePath":"guide/p2p.md"}'),l={name:"guide/p2p.md"};function s(d,t,n,u,p,h){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="气体-p2p-隧道" tabindex="-1">气体 P2P 隧道 <a class="header-anchor" href="#气体-p2p-隧道" aria-label="Permalink to &quot;气体 P2P 隧道&quot;">​</a></h1><p>气体 P2P 隧道把一段气体管路&quot;瞬移&quot;到网络的另一头：一个<strong>输入端</strong>、一个或多个<strong>输出端</strong>， 用 AE2 内存卡按标准 P2P 方式连接。</p><p><img src="'+i+'" alt="气体 P2P 隧道"></p><h2 id="为什么它必须是一只-罐" tabindex="-1">为什么它必须是一只&quot;罐&quot; <a class="header-anchor" href="#为什么它必须是一只-罐" aria-label="Permalink to &quot;为什么它必须是一只&quot;罐&quot;&quot;">​</a></h2><p>CCB 的管路求解器只和&quot;能报出真实体积&quot;的端点交换气体。如果隧道只是把气体在代码里搬来搬去， CCB 的管道会&quot;连上但不输送&quot;。所以每个隧道面都呈现一只真实的小压力容器：</p><table tabindex="0"><thead><tr><th>参数</th><th>默认值</th></tr></thead><tbody><tr><td>体积</td><td>4,000 L（可配置）</td></tr><tr><td>承压</td><td>16 atm（CCB 安全线）</td></tr><tr><td>物理容量</td><td>64,000 GU</td></tr></tbody></table><h2 id="输入与输出" tabindex="-1">输入与输出 <a class="header-anchor" href="#输入与输出" aria-label="Permalink to &quot;输入与输出&quot;">​</a></h2><ul><li><strong>输入端</strong>：线压高于缓冲罐时进气；不允许被抽走（它只负责&quot;收&quot;）。</li><li><strong>输出端</strong>：把同一只缓冲罐呈现在自己面前，相邻管网像&quot;罐就在旁边&quot;一样把气抽走。</li><li>多个输出端<strong>共抽同一只缓冲罐</strong>，不会复制气体。</li><li>输出侧被堵住时，缓冲罐充到 16 atm 就停：<strong>不丢气、不爆罐</strong>。</li></ul><h2 id="成本" tabindex="-1">成本 <a class="header-anchor" href="#成本" aria-label="Permalink to &quot;成本&quot;">​</a></h2><ul><li>有频道时 1 AE/t；</li><li>另外按<strong>实际送达输出端的气量</strong>扣 AE。</li></ul><h2 id="获得与调谐" tabindex="-1">获得与调谐 <a class="header-anchor" href="#获得与调谐" aria-label="Permalink to &quot;获得与调谐&quot;">​</a></h2><ul><li>合成获得（3 铁锭 + 工程处理器 + 密封片，具体见游戏内配方）；</li><li>或用 CCB 的气罐右击任意 P2P 隧道，把它调谐成气体隧道。</li></ul><h2 id="它不是什么" tabindex="-1">它不是什么 <a class="header-anchor" href="#它不是什么" aria-label="Permalink to &quot;它不是什么&quot;">​</a></h2><p>气体 P2P 是&quot;<strong>管路</strong>隧道&quot;：气体不进入 ME 网络，也不占元件空间。 要真正把气体存进网络，请使用 <a href="/appliedcraftedenergistics/guide/interface.html">ME 气体接口</a> 或输入 / 输出总线。</p><div class="tip custom-block"><p class="custom-block-title">与 AE2 的 ME 接口区别</p><p>ME 接口是&quot;网络与邻居交换&quot;，P2P 是&quot;同一段管路的远程延伸&quot;。 两者可以组合使用：接口负责入库，P2P 负责把气体送到远处的工厂。</p></div>',15)])])}const P=a(l,[["render",s]]);export{q as __pageData,P as default};
